('srd35_magic_crystal_ball_with_detect_thoughts','Crystal ball with detect thoughts','magic_item',51000,51000,'Listed in Table: Major Wondrous Items; market price 51,000 gp. The specific item entry is not individually written out in this SRD table.','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-v-wondrous-items.md','wondrous_items','{"source_file":"magic-items-v-wondrous-items.md","source_table":"Table: Major Wondrous Items","market_price":"51,000 gp","roll_result":"34","raw_table_row":["34","Crystal ball with detect thoughts","51,000 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":false}'::jsonb),
